    public static WorkOrderBuilding create(@NotNull WorkOrderType type, @NotNull IBuilding building) {
        int targetLevel = building.getBuildingLevel();
        switch (type) {
            case BUILD: {
                targetLevel = 1;
                break;
            }
            case UPGRADE: {
                ++targetLevel;
                break;
            }
            case REMOVE: {
                targetLevel = 0;
            }
