package com.minecolonies.core.colony.buildings.modules;

import com.minecolonies.api.colony.buildings.IBuilding;
import com.minecolonies.api.colony.managers.interfaces.IStatisticsManager;
import com.minecolonies.core.colony.buildings.modules.BuildingModules;
import com.minecolonies.core.colony.buildings.modules.BuildingStatisticsModule;
import com.minecolonies.core.colony.buildings.workerbuildings.BuildingBarracks;
import java.util.List;
import net.minecraft.core.BlockPos;
import net.minecraft.network.FriendlyByteBuf;

public class BarracksStatisticsModule
extends BuildingStatisticsModule {
    @Override
    public void serializeToView(FriendlyByteBuf buf, boolean fullSync) {
        this.getBuildingStatisticsManager().clear();
        List<BlockPos> towers = ((BuildingBarracks)this.building).getTowers();
        for (BlockPos towerPos : towers) {
            IBuilding tower = (IBuilding)this.building.getColony().getServerBuildingManager().getBuilding(towerPos);
            if (tower == null) continue;
            BuildingStatisticsModule towerStats = (BuildingStatisticsModule)tower.getModule(BuildingModules.STATS_MODULE);
            IStatisticsManager.aggregateStats(this.getBuildingStatisticsManager(), towerStats.getBuildingStatisticsManager());
        }
        this.getBuildingStatisticsManager().serialize(buf, fullSync);
    }
}

